import Foundation

/// Codex config.toml 配置字典全表（2026-10-02 依据交叉比对报告全量重建）
/// 数据源：官方 config-reference 交叉比对报告 materials/r8-doc-pull/config-reference-crosscheck-report-20261001.md
/// （2026-10-01）第二章「参数全表」297 条全表中译，为本表唯一数据来源。
/// 口径：desc／accepted 逐字取自报告（accepted 的 \| 已还原为 |，desc 行内 \| 同步还原；「【待核】」标记原样保留；
/// key 保留报告键名列原文，<id>/<name>/<path>/<index> 等占位原样）。zh 为编辑性中文名（2–8 字，自描述提炼）。
/// 保留条目 2 条（旧字典特有、报告未列）：preferred_auth_method（R25 起**废弃**：最新版 Codex 不接受、
/// 受管区不再写入；条目保留仅作废弃注记，managed=true 置灰不供添加）、mcp_servers.<id>（节键本体，供「＋添加」骨架）。
/// 受管 9 键（managed=true，置灰不可添加，skeleton 空串）：model、model_provider、model_catalog_json、forced_login_method、
/// preferred_auth_method（废弃注记）、model_providers.<id>.base_url／.name／.wire_api／.experimental_bearer_token。
/// 特例：报告将「空数组解绑」单列一行，其键名含赋值后缀（tui.keymap.<context>.<action> = []），key 照录，
/// skeleton 取规范化节头 [tui.keymap.<context>.<action>]。
/// 排序：all 数组按 key 字母序。
struct CodexConfigEntry: Identifiable {
    let key: String        // 官方键名（点路径；节键含 <id> 占位）
    let zh: String         // 中文名
    let desc: String       // 客观描述
    let accepted: String   // 接受值（查证不到填「—」）
    let managed: Bool      // true＝已被 ModelRouter 接管（置灰不可添加）
    let skeleton: String   // 「＋ 添加」写入编辑器的 TOML 骨架片段；managed 留空串
    let isSection: Bool    // skeleton 以 "[" 开头＝节键（追加文件尾）；否则顶层键（插至顶层区末尾）
    var id: String { key }
}

