        CodexConfigEntry(key: "features.hooks", zh: "钩子功能旗标", desc: "启用从 `hooks.json` 或内联 `[hooks]` 配置加载的生命周期钩子。`features.codex_hooks` 为已弃用别名。", accepted: "boolean", managed: false, skeleton: "[features]\nhooks = false", isSection: true),
        CodexConfigEntry(key: "features.memories", zh: "记忆功能旗标", desc: "启用 [Memories](https://learn.chatgpt.com/docs/customization/memories)（默认关闭）。", accepted: "boolean", managed: false, skeleton: "[features]\nmemories = false", isSection: true),
        CodexConfigEntry(key: "features.multi_agent", zh: "多代理旗标", desc: "启用多代理协作工具（`spawn_agent`、`send_input`、`resume_agent`、`wait_agent`、`close_agent`）（稳定；默认开启）。", accepted: "boolean", managed: false, skeleton: "[features]\nmulti_agent = false", isSection: true),
        CodexConfigEntry(key: "features.network_proxy", zh: "网络代理功能", desc: "为沙箱命令启动网络代理（实验性；默认关闭）。除非已启用的管理员受管 `experimental_network` 要求会启动代理，权限档域名规则的执行需要它【待核】。设置 `domains` 等功能级策略选项时用表形态。不过滤网页搜索、应用、MCP 及其他托管工具。", accepted: "boolean | table", managed: false, skeleton: "[features.network_proxy]", isSection: true),
        CodexConfigEntry(key: "features.network_proxy.allow_local_binding", zh: "本地绑定放宽", desc: "允许更宽的本地/私有网络访问。默认 `false`；精确的本地 IP 字面量或 `localhost` allow 规则仍可放行特定本地目标。", accepted: "boolean", managed: false, skeleton: "[features.network_proxy]\nallow_local_binding = false", isSection: true),
        CodexConfigEntry(key: "features.network_proxy.allow_upstream_proxy", zh: "上游代理串联", desc: "允许经来自环境的上游代理串联。默认 `true`。", accepted: "boolean", managed: false, skeleton: "[features.network_proxy]\nallow_upstream_proxy = false", isSection: true),
        CodexConfigEntry(key: "features.network_proxy.dangerously_allow_all_unix_sockets", zh: "允许任意套接字", desc: "允许任意 Unix socket 目的地，取代仅允许清单式访问。默认 `false`；仅在严格受控环境使用。", accepted: "boolean", managed: false, skeleton: "[features.network_proxy]\ndangerously_allow_all_unix_sockets = false", isSection: true),
        CodexConfigEntry(key: "features.network_proxy.dangerously_allow_non_loopback_proxy", zh: "允许非环回监听", desc: "允许非 loopback 监听地址。默认 `false`；启用后代理监听可能暴露到 localhost 之外。", accepted: "boolean", managed: false, skeleton: "[features.network_proxy]\ndangerously_allow_non_loopback_proxy = false", isSection: true),
        CodexConfigEntry(key: "features.network_proxy.domains", zh: "域名策略", desc: "沙箱网络的域名策略。默认未设，即添加 `allow` 规则前不允许任何外部目的地。支持精确主机、仅子域的 `*.example.com`、含主域与子域的 `**.example.com`，以及全局 `*` allow 规则。建议用带范围的规则，因为 `*` 会广泛开放公网出站访问。为被拦目的地添加 `deny` 规则；冲突时 `deny` 胜出。", accepted: "map<string, allow | deny>", managed: false, skeleton: "[features.network_proxy.domains]", isSection: true),
        CodexConfigEntry(key: "features.network_proxy.enable_socks5", zh: "SOCKS5 开关", desc: "暴露 SOCKS5 支持。默认 `true`。", accepted: "boolean", managed: false, skeleton: "[features.network_proxy]\nenable_socks5 = false", isSection: true),
        CodexConfigEntry(key: "features.network_proxy.enable_socks5_udp", zh: "SOCKS5 UDP", desc: "允许 SOCKS5 承载 UDP。默认 `true`。", accepted: "boolean", managed: false, skeleton: "[features.network_proxy]\nenable_socks5_udp = false", isSection: true),
        CodexConfigEntry(key: "features.network_proxy.enabled", zh: "代理启用", desc: "命令网络访问开启时启动沙箱命令网络代理。默认 `false`；代理关闭期间权限档域名规则不被执行。", accepted: "boolean", managed: false, skeleton: "[features.network_proxy]\nenabled = false", isSection: true),
        CodexConfigEntry(key: "features.network_proxy.proxy_url", zh: "代理监听地址", desc: "沙箱网络的 HTTP 监听 URL。默认 `\"http://127.0.0.1:3128\"`。", accepted: "string", managed: false, skeleton: "[features.network_proxy]\nproxy_url = \"\"", isSection: true),
        CodexConfigEntry(key: "features.network_proxy.socks_url", zh: "SOCKS 监听地址", desc: "SOCKS5 监听 URL。默认 `\"http://127.0.0.1:8081\"`。", accepted: "string", managed: false, skeleton: "[features.network_proxy]\nsocks_url = \"\"", isSection: true),
        CodexConfigEntry(key: "features.network_proxy.unix_sockets", zh: "Unix 套接字策略", desc: "沙箱网络的 Unix socket 策略。默认未设；为允许的 socket 添加 `allow` 条目。", accepted: "map<string, allow | deny>", managed: false, skeleton: "[features.network_proxy.unix_sockets]", isSection: true),
        CodexConfigEntry(key: "features.personality", zh: "个性旗标", desc: "启用个性选择控件（稳定；默认开启）。", accepted: "boolean", managed: false, skeleton: "[features]\npersonality = false", isSection: true),
        CodexConfigEntry(key: "features.prevent_idle_sleep", zh: "阻止休眠旗标", desc: "回合运行期间阻止机器休眠（实验性；默认关闭）。", accepted: "boolean", managed: false, skeleton: "[features]\nprevent_idle_sleep = false", isSection: true),
        CodexConfigEntry(key: "features.remote_plugin", zh: "远程插件旗标", desc: "启用远程插件目录（稳定；默认开启）。", accepted: "boolean", managed: false, skeleton: "[features]\nremote_plugin = false", isSection: true),
        CodexConfigEntry(key: "features.rollout_budget.enabled", zh: "预算跟踪开关", desc: "启用 rollout 预算跟踪。该功能开发中，默认关闭。启用时必须提供 `features.rollout_budget.limit_tokens`。", accepted: "boolean", managed: false, skeleton: "[features.rollout_budget]\nenabled = false", isSection: true),
        CodexConfigEntry(key: "features.rollout_budget.limit_tokens", zh: "预算上限", desc: "rollout 预算跟踪的正数 token 上限。启用 rollout 预算时必填。", accepted: "integer", managed: false, skeleton: "[features.rollout_budget]\nlimit_tokens = 0", isSection: true),
        CodexConfigEntry(key: "features.rollout_budget.prefill_token_weight", zh: "预填充权重", desc: "rollout 预算核算中预填充 token 的有限非负乘数。默认 `1.0`。", accepted: "number", managed: false, skeleton: "[features.rollout_budget]\nprefill_token_weight = 0", isSection: true),
        CodexConfigEntry(key: "features.rollout_budget.reminder_interval_tokens", zh: "预算提醒间隔", desc: "rollout 预算提醒之间的正数 token 间隔。默认 `limit_tokens` 的 10%，最小 1 token。", accepted: "integer", managed: false, skeleton: "[features.rollout_budget]\nreminder_interval_tokens = 0", isSection: true),
        CodexConfigEntry(key: "features.rollout_budget.sampling_token_weight", zh: "采样权重", desc: "rollout 预算核算中采样 token 的有限非负乘数。默认 `1.0`。", accepted: "number", managed: false, skeleton: "[features.rollout_budget]\nsampling_token_weight = 0", isSection: true),
        CodexConfigEntry(key: "features.shell_snapshot", zh: "Shell 快照旗标", desc: "对 shell 环境做快照以加速重复命令（稳定；默认开启）。", accepted: "boolean", managed: false, skeleton: "[features]\nshell_snapshot = false", isSection: true),
        CodexConfigEntry(key: "features.shell_tool", zh: "Shell 工具旗标", desc: "启用运行命令的默认 `shell` 工具（稳定；默认开启）。", accepted: "boolean", managed: false, skeleton: "[features]\nshell_tool = false", isSection: true),
        CodexConfigEntry(key: "features.skill_mcp_dependency_install", zh: "依赖安装旗标", desc: "允许就技能缺失的 MCP 依赖进行提示并安装（稳定；默认开启）。", accepted: "boolean", managed: false, skeleton: "[features]\nskill_mcp_dependency_install = false", isSection: true),
        CodexConfigEntry(key: "features.unified_exec", zh: "统一执行旗标", desc: "使用统一的 PTY 执行工具（稳定；默认启用，Windows 除外）。", accepted: "boolean", managed: false, skeleton: "[features]\nunified_exec = false", isSection: true),
        CodexConfigEntry(key: "features.web_search", zh: "网页搜索旧旗标", desc: "已弃用的旧开关；建议改用顶层 `web_search` 设置。", accepted: "boolean", managed: false, skeleton: "[features]\nweb_search = false", isSection: true),
        CodexConfigEntry(key: "features.web_search_cached", zh: "缓存搜索旧旗标", desc: "已弃用的旧开关。`web_search` 未设时，true 映射为 `web_search = \"cached\"`。", accepted: "boolean", managed: false, skeleton: "[features]\nweb_search_cached = false", isSection: true),
        CodexConfigEntry(key: "features.web_search_request", zh: "实时搜索旧旗标", desc: "已弃用的旧开关。`web_search` 未设时，true 映射为 `web_search = \"live\"`。", accepted: "boolean", managed: false, skeleton: "[features]\nweb_search_request = false", isSection: true),
        CodexConfigEntry(key: "feedback.enabled", zh: "反馈开关", desc: "在各本地客户端中启用经 `/feedback` 提交反馈（默认：true）。", accepted: "boolean", managed: false, skeleton: "[feedback]\nenabled = false", isSection: true),
        CodexConfigEntry(key: "file_opener", zh: "文件打开方式", desc: "打开 Codex 输出中引用所用的 URI scheme（默认：`vscode`）。", accepted: "vscode | vscode-insiders | windsurf | cursor | none", managed: false, skeleton: "file_opener = \"vscode\"", isSection: false),
        CodexConfigEntry(key: "forced_chatgpt_workspace_id", zh: "强制工作区", desc: "把 ChatGPT 登录限定到特定工作区标识。", accepted: "string (uuid)", managed: false, skeleton: "forced_chatgpt_workspace_id = \"\"", isSection: false),
        CodexConfigEntry(key: "forced_login_method", zh: "强制登录方式", desc: "限制 Codex 只用特定认证方式。", accepted: "chatgpt | api", managed: true, skeleton: "", isSection: false),
        CodexConfigEntry(key: "hide_agent_reasoning", zh: "隐藏推理", desc: "在 TUI 与 `codex exec` 输出中抑制推理事件。", accepted: "boolean", managed: false, skeleton: "hide_agent_reasoning = false", isSection: false),
        CodexConfigEntry(key: "history.max_bytes", zh: "历史字节上限", desc: "若设置，按字节封顶历史文件大小，超出时丢弃最旧条目。", accepted: "number", managed: false, skeleton: "[history]\nmax_bytes = 0", isSection: true),
        CodexConfigEntry(key: "history.persistence", zh: "历史保存策略", desc: "控制 Codex 是否把会话记录保存到 history.jsonl。", accepted: "save-all | none", managed: false, skeleton: "[history]\npersistence = \"save-all\"", isSection: true),
        CodexConfigEntry(key: "hooks", zh: "生命周期钩子", desc: "在 `config.toml` 内联配置的生命周期钩子。事件 schema 与 `hooks.json` 相同；示例与受支持事件见 Hooks 指南。", accepted: "table", managed: false, skeleton: "[hooks]", isSection: true),
        CodexConfigEntry(key: "hooks.<Event>", zh: "钩子事件", desc: "各类钩子事件（如 `PreToolUse`、`PermissionRequest`、`PostToolUse`、`PreCompact`、`PostCompact`、`SessionStart`、`SessionEnd`、`SubagentStart`、`SubagentStop`、`UserPromptSubmit`、`Stop`、`Interrupt`）的匹配器组。", accepted: "array<table>", managed: false, skeleton: "[hooks.<Event>]", isSection: true),
        CodexConfigEntry(key: "hooks.<Event>[].hooks", zh: "钩子处理器", desc: "匹配器组的钩子处理器。支持命令与 MCP 工具钩子；prompt 与 agent 处理器会被解析但跳过。", accepted: "array<table>", managed: false, skeleton: "[hooks.<Event>[]]\nhooks = []", isSection: true),
        CodexConfigEntry(key: "hooks.<Event>[].hooks[].additionalContextLimit", zh: "上下文阈值", desc: "每个处理器的近似 token 阈值：超限的 `additionalContext` 存盘并向模型展示较短预览。默认 `2500`；`0` 表示把完整上下文直接交给模型。参见 [Large hook output](https://learn.chatgpt.com/docs/hooks#large-hook-output)。", accepted: "integer", managed: false, skeleton: "[hooks.<Event>[].hooks[]]\nadditionalContextLimit = 0", isSection: true),
        CodexConfigEntry(key: "hooks.<Event>[].hooks[].async", zh: "后台运行钩子", desc: "在后台运行命令钩子而不延迟触发操作。默认 `false`；`SessionEnd` 始终同步运行。参见 [Run hooks in the background](https://learn.chatgpt.com/docs/hooks#run-hooks-in-the-background)。", accepted: "boolean", managed: false, skeleton: "[hooks.<Event>[].hooks[]]\nasync = false", isSection: true),
        CodexConfigEntry(key: "hooks.<Event>[].hooks[].commandWindows", zh: "Windows 命令", desc: "仅限 Windows 的命令钩子命令覆盖。也接受 TOML 别名 `command_windows`。", accepted: "string", managed: false, skeleton: "[hooks.<Event>[].hooks[]]\ncommandWindows = \"\"", isSection: true),
        CodexConfigEntry(key: "instructions", zh: "预留指令", desc: "预留供将来使用；建议改用 `model_instructions_file` 或 `AGENTS.md`。", accepted: "string", managed: false, skeleton: "instructions = \"\"", isSection: false),
        CodexConfigEntry(key: "log_dir", zh: "日志目录", desc: "Codex 写日志文件的目录；默认 `$CODEX_HOME/log`。显式设置后，该目录下还会启用可选的纯文本 TUI 日志 `codex-tui.log`。", accepted: "string (path)", managed: false, skeleton: "log_dir = \"\"", isSection: false),
        CodexConfigEntry(key: "marketplaces.<name>.ref", zh: "市场 Git 引用", desc: "市场的可选 Git 分支、标签或提交。", accepted: "string", managed: false, skeleton: "[marketplaces.<name>]\nref = \"\"", isSection: true),
        CodexConfigEntry(key: "marketplaces.<name>.source", zh: "市场来源", desc: "Git 仓库位置或本地市场根目录。本地来源用绝对路径；该目录含 .agents/plugins/marketplace.json。", accepted: "string", managed: false, skeleton: "[marketplaces.<name>]\nsource = \"\"", isSection: true),
        CodexConfigEntry(key: "marketplaces.<name>.source_type", zh: "市场来源类型", desc: "插件市场的来源类型。市场可定义于系统、云受管、用户或受信项目的 config.toml。", accepted: "git | local", managed: false, skeleton: "[marketplaces.<name>]\nsource_type = \"git\"", isSection: true),
        CodexConfigEntry(key: "marketplaces.<name>.sparse_paths", zh: "稀疏检出路径", desc: "Git 市场的可选稀疏检出路径。须含市场目录及其引用的本地插件目录。", accepted: "array<string>", managed: false, skeleton: "[marketplaces.<name>]\nsparse_paths = []", isSection: true),
        CodexConfigEntry(key: "mcp_oauth_callback_port", zh: "OAuth 回调端口", desc: "MCP OAuth 登录所用本地 HTTP 回调服务器的可选全局固定端口。服务器专属的 `oauth.callback_port` 优先。两者都未设时，Codex 绑定 OS 选择的临时端口。", accepted: "integer", managed: false, skeleton: "mcp_oauth_callback_port = 0", isSection: false),
        CodexConfigEntry(key: "mcp_oauth_callback_url", zh: "基础回调地址", desc: "MCP OAuth 登录的可选基础回调 URL，如 devbox 入口 URL。授权服务器支持 issuer 识别时，新增预注册客户端原样使用此 URL；无已存回调的既有客户端附加服务器专属回调 ID。不支持 issuer 识别时，配置回调缺少所需 ID 的任何预注册 MCP 服务器回退到此 URL 并附加该 ID。回调 URL 的端口不选择监听端口。【待核】", accepted: "string", managed: false, skeleton: "mcp_oauth_callback_url = \"\"", isSection: false),
        CodexConfigEntry(key: "mcp_oauth_credentials_store", zh: "OAuth 凭据存储", desc: "MCP OAuth 凭据的首选存储。", accepted: "auto | file | keyring", managed: false, skeleton: "mcp_oauth_credentials_store = \"auto\"", isSection: false),
        CodexConfigEntry(key: "mcp_optional_startup_grace_ms", zh: "MCP 启动宽限", desc: "构建初始工具目录时对可选 MCP 服务器的共享等待。默认 `1000`。设为 `0` 则改为等待各服务器的 `startup_timeout_sec`。", accepted: "integer (milliseconds)", managed: false, skeleton: "mcp_optional_startup_grace_ms = 0", isSection: false),
        CodexConfigEntry(key: "mcp_servers.<id>", zh: "MCP 服务器", desc: "接入 MCP 服务器：command/args/env 本地进程，或 url 远程端点。", accepted: "表", managed: false, skeleton: "[mcp_servers.<name>]\ncommand = \"\"", isSection: true),
        CodexConfigEntry(key: "mcp_servers.<id>.args", zh: "启动参数", desc: "传给 MCP stdio 服务器命令的参数。", accepted: "array<string>", managed: false, skeleton: "[mcp_servers.<id>]\nargs = []", isSection: true),
        CodexConfigEntry(key: "mcp_servers.<id>.auth", zh: "认证兜底", desc: "MCP HTTP 服务器在已配置 bearer token 与鉴权头之后的认证兜底。`oauth`（默认）在可用时使用已存 MCP OAuth 凭据。`chatgpt` 对受信第一方 ChatGPT 来源使用当前 ChatGPT 会话，之后回退到已存 OAuth。两种模式在无凭据来源可解析时都可无认证连接。", accepted: "oauth | chatgpt", managed: false, skeleton: "[mcp_servers.<id>]\nauth = \"oauth\"", isSection: true),
        CodexConfigEntry(key: "mcp_servers.<id>.bearer_token_env_var", zh: "Bearer 环境变量", desc: "为 MCP HTTP 服务器提供 bearer token 的环境变量。", accepted: "string", managed: false, skeleton: "[mcp_servers.<id>]\nbearer_token_env_var = \"\"", isSection: true),
        CodexConfigEntry(key: "mcp_servers.<id>.command", zh: "启动命令", desc: "MCP stdio 服务器的启动命令。", accepted: "string", managed: false, skeleton: "[mcp_servers.<id>]\ncommand = \"\"", isSection: true),
        CodexConfigEntry(key: "mcp_servers.<id>.cwd", zh: "工作目录", desc: "MCP stdio 服务器进程的工作目录。", accepted: "string", managed: false, skeleton: "[mcp_servers.<id>]\ncwd = \"\"", isSection: true),
        CodexConfigEntry(key: "mcp_servers.<id>.default_tools_approval_mode", zh: "MCP 默认审批", desc: "此服务器上 MCP 工具的默认审批行为，除非存在按工具覆盖。", accepted: "auto | prompt | writes | approve", managed: false, skeleton: "[mcp_servers.<id>]\ndefault_tools_approval_mode = \"auto\"", isSection: true),
        CodexConfigEntry(key: "mcp_servers.<id>.disabled_tools", zh: "工具拒绝清单", desc: "在 `enabled_tools` 之后应用的 MCP 服务器拒绝清单。", accepted: "array<string>", managed: false, skeleton: "[mcp_servers.<id>]\ndisabled_tools = []", isSection: true),
        CodexConfigEntry(key: "mcp_servers.<id>.enabled", zh: "服务器启用", desc: "在不删除配置的情况下停用 MCP 服务器。", accepted: "boolean", managed: false, skeleton: "[mcp_servers.<id>]\nenabled = false", isSection: true),
        CodexConfigEntry(key: "mcp_servers.<id>.enabled_tools", zh: "工具允许清单", desc: "MCP 服务器暴露工具名的允许清单。", accepted: "array<string>", managed: false, skeleton: "[mcp_servers.<id>]\nenabled_tools = []", isSection: true),
        CodexConfigEntry(key: "mcp_servers.<id>.env", zh: "环境变量表", desc: "转发给 MCP stdio 服务器的环境变量。", accepted: "map<string,string>", managed: false, skeleton: "[mcp_servers.<id>.env]", isSection: true),
        CodexConfigEntry(key: "mcp_servers.<id>.env_http_headers", zh: "环境变量请求头", desc: "MCP HTTP 服务器从环境变量取值的 HTTP 头。", accepted: "map<string,string>", managed: false, skeleton: "[mcp_servers.<id>.env_http_headers]", isSection: true),
        CodexConfigEntry(key: "mcp_servers.<id>.env_vars", zh: "环境变量白名单", desc: "为 MCP stdio 服务器额外加入白名单的环境变量。字符串条目默认 `source = \"local\"`；`source = \"remote\"` 仅用于执行器承载的远程 stdio。", accepted: "array<string | { name = string, source = \"local\" | \"remote\" }>", managed: false, skeleton: "[mcp_servers.<id>]\nenv_vars = []", isSection: true),
        CodexConfigEntry(key: "mcp_servers.<id>.experimental_environment", zh: "实验放置方式", desc: "MCP 服务器的实验性放置方式。`remote` 经远程执行器环境启动 stdio 服务器；streamable HTTP 的远程放置未实现。", accepted: "local | remote", managed: false, skeleton: "[mcp_servers.<id>]\nexperimental_environment = \"local\"", isSection: true),
        CodexConfigEntry(key: "mcp_servers.<id>.http_headers", zh: "静态请求头", desc: "每个 MCP HTTP 请求附带的静态 HTTP 头。", accepted: "map<string,string>", managed: false, skeleton: "[mcp_servers.<id>.http_headers]", isSection: true),
