        CodexConfigEntry(key: "tools.web_search", zh: "网页搜索配置", desc: "可选的网页搜索工具配置。对象形态可设搜索上下文大小、允许的搜索域名与近似用户位置。这些搜索域过滤与沙箱命令网络域规则相互独立，不限制连接器或 MCP 服务器。", accepted: "boolean | { context_size = \"low|medium|high\", allowed_domains = [string], location = { country, region, city, timezone } }", managed: false, skeleton: "[tools.web_search]", isSection: true),
        CodexConfigEntry(key: "tui", zh: "TUI 选项", desc: "TUI 专属选项，例如启用内联桌面通知。", accepted: "table", managed: false, skeleton: "[tui]", isSection: true),
        CodexConfigEntry(key: "tui.alternate_screen", zh: "备用屏幕", desc: "控制 TUI 对备用屏幕的使用（默认：auto；auto 在 Zellij 中跳过备用屏以保留回滚）。", accepted: "auto | always | never", managed: false, skeleton: "[tui]\nalternate_screen = \"auto\"", isSection: true),
        CodexConfigEntry(key: "tui.animations", zh: "终端动画", desc: "启用终端动画（欢迎屏、微光、加载指示）（默认：true）。", accepted: "boolean", managed: false, skeleton: "[tui]\nanimations = false", isSection: true),
        CodexConfigEntry(key: "tui.keymap.<context>.<action>", zh: "快捷键绑定", desc: "TUI 动作的快捷键绑定。支持的 context 包括 `global`、`chat`、`composer`、`editor`、`vim_normal`、`vim_operator`、`vim_text_object`、`pager`、`list`、`approval`。选定的 composer 动作会回退到匹配的 `tui.keymap.global` 绑定；受支持时 context 专属绑定优先。", accepted: "string | array<string>", managed: false, skeleton: "[tui.keymap.<context>.<action>]", isSection: true),
        CodexConfigEntry(key: "tui.keymap.<context>.<action> = []", zh: "快捷键解绑", desc: "在该 keymap context 中解除该动作的绑定。键名使用规范化字符串，如 `ctrl-a`、`shift-enter`、`page-down`、`minus`。", accepted: "empty array", managed: false, skeleton: "[tui.keymap.<context>.<action>]", isSection: true),
        CodexConfigEntry(key: "tui.model_availability_nux.<model>", zh: "模型提示状态", desc: "按模型 slug 为键的内部启动提示状态。", accepted: "integer", managed: false, skeleton: "[tui.model_availability_nux.<model>]", isSection: true),
        CodexConfigEntry(key: "tui.notification_condition", zh: "通知条件", desc: "控制 TUI 通知仅在终端失焦时触发，还是不论焦点。默认 `unfocused`。", accepted: "unfocused | always", managed: false, skeleton: "[tui]\nnotification_condition = \"unfocused\"", isSection: true),
        CodexConfigEntry(key: "tui.notification_method", zh: "通知方式", desc: "终端通知的方式（默认：auto）。", accepted: "auto | osc9 | bel", managed: false, skeleton: "[tui]\nnotification_method = \"auto\"", isSection: true),
        CodexConfigEntry(key: "tui.notifications", zh: "TUI 通知", desc: "启用 TUI 通知；可选择性限制为特定事件类型。", accepted: "boolean | array<string>", managed: false, skeleton: "[tui]\nnotifications = false", isSection: true),
        CodexConfigEntry(key: "tui.raw_output_mode", zh: "原始回滚模式", desc: "以原始回滚模式启动 TUI，便于在终端中复制所选内容（默认：false）。可用 `/raw` 或默认 `alt-r` 键位切换。", accepted: "boolean", managed: false, skeleton: "[tui]\nraw_output_mode = false", isSection: true),
        CodexConfigEntry(key: "tui.resume_cwd", zh: "恢复工作目录", desc: "恢复或分叉会话时使用的工作目录。未设置且当前目录与会话保存目录不同时，Codex 会请你选择。", accepted: "current | session", managed: false, skeleton: "[tui]\nresume_cwd = \"current\"", isSection: true),
        CodexConfigEntry(key: "tui.show_tooltips", zh: "新手提示", desc: "在 TUI 欢迎屏显示新手提示（默认：true）。", accepted: "boolean", managed: false, skeleton: "[tui]\nshow_tooltips = false", isSection: true),
        CodexConfigEntry(key: "tui.status_line", zh: "状态栏", desc: "TUI 底部状态栏条目标识的有序列表。`null` 关闭状态栏。", accepted: "array<string> | null", managed: false, skeleton: "[tui]\nstatus_line = []", isSection: true),
        CodexConfigEntry(key: "tui.terminal_title", zh: "终端标题", desc: "终端窗口/标签标题条目标识的有序列表。默认 `[\"spinner\", \"project\"]`；`null` 关闭标题更新。", accepted: "array<string> | null", managed: false, skeleton: "[tui]\nterminal_title = []", isSection: true),
        CodexConfigEntry(key: "tui.theme", zh: "TUI 主题", desc: "语法高亮主题覆盖（kebab-case 主题名）。", accepted: "string", managed: false, skeleton: "[tui]\ntheme = \"\"", isSection: true),
        CodexConfigEntry(key: "tui.vim_mode_default", zh: "Vim 默认模式", desc: "输入框以 Vim normal 模式而非插入模式启动（默认：false）。仍可在会话内用 `/vim` 切换。", accepted: "boolean", managed: false, skeleton: "[tui]\nvim_mode_default = false", isSection: true),
        CodexConfigEntry(key: "web_search", zh: "网页搜索模式", desc: "网页搜索模式（默认：`\"cached\"`；cached 使用 OpenAI 维护的索引，不做外部网页访问；indexed 仅在被搜索索引把关时允许外部访问；使用 `--yolo` 或其他完全访问沙箱设置时默认 `\"live\"`）。`\"live\"` 为不受限的实时检索；`\"disabled\"` 移除该工具。", accepted: "disabled | cached | indexed | live", managed: false, skeleton: "web_search = \"disabled\"", isSection: false),
        CodexConfigEntry(key: "windows.sandbox", zh: "Windows 沙箱", desc: "仅限 Windows：在 Windows 上原生运行 Codex 时的原生沙箱模式。", accepted: "unelevated | elevated | mxc", managed: false, skeleton: "[windows]\nsandbox = \"unelevated\"", isSection: true),
        CodexConfigEntry(key: "windows_wsl_setup_acknowledged", zh: "WSL 引导确认", desc: "记录 Windows 引导流程的确认状态（仅 Windows）。", accepted: "boolean", managed: false, skeleton: "windows_wsl_setup_acknowledged = false", isSection: false),
    ]
}
